SELECT a.term_id, a.bot_id, a.scene_id, a.tenant_id, a.term_content, a.term_type, a.owner_type, a.created_time, a.status_cd, a.updated_time, a.creator_id, a.updator_id, a.remark, t.tenant_name, b.bot_name, s.scene_name, u.real_name AS "updatorName" FROM bt_suggestion_term a LEFT JOIN bt_tenant t ON t.tenant_id = a.tenant_id AND t.status_cd = '00A' LEFT JOIN bt_bot b ON b.bot_id = a.bot_id AND b.tenant_id = a.tenant_id AND b.status_cd = '00A' LEFT JOIN bt_bot_scene s ON s.scene_id = a.scene_id AND s.tenant_id = a.tenant_id AND s.status_cd = '00A' LEFT JOIN bt_user u ON u.user_id = a.updator_id AND u.status_cd = '00A' WHERE a.status_cd = '00A'
AND a.term_type = #{query.termType}
AND a.owner_type = #{query.ownerType}
AND a.tenant_id = #{query.tenantId}
AND a.bot_id = #{query.botId}
AND a.scene_id = #{query.sceneId}
AND a.term_content LIKE
#{query.searchContent}
ORDER BY a.updated_time DESC

